from write_dossiers import add

add('hamt',year=2021,venue='NeurIPS 2021',pages=[1,3,4,5,6,7,8],
problem='Long navigation histories cannot be reconstructed reliably from a fixed recurrent state. HAMT receives the instruction, all previous panoramic observations/actions, and the current panorama, then predicts the next navigable direction or STOP. Its graph-navigation experiments assume viewpoint localization and candidate directions; those assumptions are distinct from low-level robot control.',
method='PDF pp3–5: each panoramic view is encoded by a ViT; a panorama Transformer aggregates its K views, combining pooled panoramic context with the orientation-specific view. A temporal Transformer encodes the resulting history tokens, action directions, and step embeddings. A cross-modal Transformer jointly reasons over text, history, and current candidates. The hidden dimension is 768; reported configuration uses 9 language, 2 panorama, and 4 cross-modal layers. With t steps and K views, hierarchical attention costs O(tK²+t²), versus O(t²K²) for flattened history. This reduces attention cost but does not make memory constant. Pretraining combines masked language/region prediction, instruction–trajectory matching, single-action CE, action-angle squared error, and spatial-relation regression. In the latter, the target is the relative heading/elevation between two views and masking prevents trivial copying. Fine-tuning minimizes imitation CE plus an A3C policy/value/entropy objective; the supervised action term is −Σt log π(a*t|W,Ht,Ot). The reported imitation weight is 0.2 and discount 0.9. Training first freezes the ViT for 200k steps (4 P100), then updates it for 20k steps (20 V100); fine-tuning is 100k steps with batch 8. Inference greedily selects a candidate from the history-conditioned logits without search.',
novelty='Explicit hierarchical history encoding and end-to-end visual adaptation are the principal mechanisms. The paper introduces R2R-Back and R2R-Last to probe history requirements. It does not introduce global graph action selection: history tokens influence a local action policy. Table2 isolates the hierarchy with the same ResNet feature family; Table3 separates proxy training, ViT features, and visual fine-tuning.',
results='AUTHOR EXPERIMENT: Table2 p7 reports hierarchical-from-scratch SR 54.4±0.4 versus recurrent 52.2±0.7; Table3 p8 shows much larger changes from pretraining and vision adaptation (ResNet no pretraining 54.4 SR; proxy-trained ResNet 63.5; ViT 64.4; end-to-end 65.7). Table4 gives IL-only 57.2, RL-only 63.5, combined 65.7 SR. VERDICT: explicit history helps under matched features, but attributing the entire headline gain to memory would be incorrect. The cost analysis and limited trajectory lengths do not establish scalability to lifelong navigation.',
implementation='Inspected hierarchical history embeddings, multimodal navigation forward path, pretraining heads, and the imitation/RL optimizer loop. No training, dataset preprocessing, checkpoint load, or simulator evaluation was executed.',
code=[dict(path='finetune_src/models/vilmodel_cmt.py',locator='HistoryEmbeddings lines523–559; NavCMT lines624–629',finding='History encodes temporal and panoramic structure and is passed alongside current visual observations into cross-modal navigation.'),dict(path='finetune_src/r2r/agent_cmt.py',locator='training paths lines549 and584–602',finding='Imitation and reinforcement updates are explicit; gradients are clipped at40 before optimizer steps.'),dict(path='pretrain_src/model/pretrain_cmt.py',locator='task-dispatch and prediction-head definitions',finding='Separate proxy heads implement the paper’s multi-task pretraining; this is training-time supervision, not an inference-time planner.')],
bottlenecks=[dict(description='History storage grows with episode length and temporal attention remains quadratic in t.',evidence='PDF §3 hierarchy and complexity discussion pp3–5',kind='architectural',status='Partially addressed',followups=['DUET topological map aggregation','GridMM spatial memory'],confidence='high'),dict(description='A local candidate policy must discover its own multi-step return decisions even with rich history; explicit graph routing is not present.',evidence='PDF action prediction pp4–5; inspected NavCMT',kind='methodological',status='Partially addressed',followups=['DUET global graph actions'],confidence='high')],followups=['https://github.com/cshizhe/VLN-DUET','https://github.com/MrZihan/GridMM'])

add('vlnbert',year=2021,venue='CVPR 2021',title='VLN BERT: A Recurrent Vision-and-Language BERT for Navigation',pages=[1,3,4,5,6],
problem='Adapt pretrained vision–language Transformers to sequential, partially observed action selection without an additional LSTM navigation backbone. This is the recurrent VLN-BERT paper by Hong et al., not the earlier discriminative VLN-BERT path-ranking paper.',
method='PDF §3 pp3–5: encode the instruction once and use its CLS output as initial state s0∈R^d. At each step a Transformer consumes recurrent state st−1 and current panoramic candidates, attending to fixed language features. Text and visual attention summaries are multiplied elementwise and concatenated with the raw state before projection (Eq12); the selected action angle is incorporated into the next state (Eq13). Attention from the state to visual candidates supplies the action distribution. REVERIE additionally predicts the target object and adapts state refinement. OSCAR and PREVALENT initializations are separate variants; the PREVALENT implementation adapts its cross-modal architecture for recurrent state+vision inputs. Eq14 combines actor-critic RL with supervised imitation CE; the scalar policy term uses discounted advantage and the supervised term −logπ(a*t). Object grounding adds CE on REVERIE. Reported AdamW learning rate is 1e−5; R2R300k steps/batch16 and REVERIE200k/batch8 on one2080Ti. Inference recurrently updates the state and greedily acts, rather than ranking complete paths.',
novelty='The contribution is recurrent reuse of a pretrained multimodal Transformer and state-directed attention for navigation. Initialization and architecture are jointly important: Table1 compares random, OSCAR, and PREVALENT variants. It should not be grouped as a general-purpose instruction-following VLM with training-free inference.',
results='AUTHOR EXPERIMENT: Table1 p6 reports R2R test SR/SPL63/57 for PREVALENT initialization,57/53 for OSCAR,51/47 for random initialization. Table2 reports REVERIE test SR29.61, remote-grounding success16.50 and RGSPL13.51. VERDICT: substantial pretrained-representation benefit is evident, but comparisons do not independently establish semantic reasoning or resilience to long-history aliasing.',
implementation='Inspected PREVALENT recurrent Transformer, policy/optimization loop, training driver, and evaluation file. Paper and code agree that state and visual inputs evolve while the language representation serves as persistent context.',
code=[dict(path='r2r_src/vlnbert/vlnbert_PREVALENT.py',locator='forward lines322–327 and mode dispatch near384',finding='The recurrent state is concatenated with current visual features for the visual/cross-modal branch.'),dict(path='r2r_src/agent.py',locator='lines527–544',finding='Imitation and RL losses are optimized with gradient clipping40.'),dict(path='r2r_src/eval.py',locator='Evaluation scoring functions',finding='Scoring computes endpoint and path measures; no instruction counterfactual evaluation is implemented in the inspected evaluator.')],
bottlenecks=[dict(description='A fixed-dimensional state must compress the full trajectory, so histories requiring distinct decisions can become aliased.',evidence='Eq12–13 and recurrent state architecture; this is a capacity deduction, not a demonstrated universal failure',kind='architectural',status='Partially addressed',followups=['HAMT explicit history','DUET graph memory'],confidence='medium'),dict(description='Headline accuracy depends strongly on pretrained initialization; pure architecture claims need matched initialization/data controls.',evidence='Table1 p6 random versus OSCAR/PREVALENT',kind='experimental confounding',status='Partially addressed',followups=['HAMT Table2 matched-feature comparison'],confidence='high')],followups=['https://github.com/cshizhe/VLN-HAMT'])

add('airbert',year=2021,venue='ICCV 2021',pages=[1,3,4,5,6,7],
problem='Reduce the domain gap between generic web image–text pretraining and indoor instruction navigation without requiring new embodied human demonstrations. The BnB corpus uses approximately140k rental listings,1.4M images and0.7M captions; images in one listing need not form a physically traversable trajectory.',
method='PDF pp3–5: clean rental images/captions, sample4–7-image pseudo-paths from a listing, merge room views, concatenate captions, insert uncaptained views, and create instructions by template noun substitution or generation. A ViLBERT-style two-stream model encodes language tokens and visual regions with image separators. Besides masked token/region prediction, the shuffling objective contrasts a matched trajectory–instruction pair against shuffled order negatives. In Eq3, for scalar compatibility sθ(V,W), L=−log[exp sθ(V,W)/(exp sθ(V,W)+Σn exp sθ(Vn−,Wn−))]; the contrast concerns ordering compatibility, not physical transition validity. The model supports two distinct downstream uses: discriminative reranking of explored complete trajectories, and initialization of recurrent VLN-BERT for action generation. These inference protocols must remain separated.',
novelty='In-domain non-embodied pretraining and order-sensitive shuffling are the mechanisms. The synthetic-path construction supplies scale but sacrifices measured geometry. Table2 tests construction choices, Table3 tests pretraining, and Table5 tests noun/direction corruptions: this is relevant prior art for proposals based on counterfactual instruction discrimination.',
results='AUTHOR EXPERIMENT: Table2 p6 reports62.45 SR with image-caption training versus66.52 with rephrasing/merge/insertion; Table3 full pretraining reaches68.67. Table5 unseen direction-corruption discrimination is49.8 versus45.3 for VLN-BERT; noun-swap61.1 versus52.3. Critical protocol correction: Table8 p7 test SR77 uses pre-exploration and a687m trajectory with SPL0.01. It is not comparable to single-run navigation; recurrent AirBERT is a separate result. VERDICT: transfer and order discrimination improve, while the weak direction test and physically ungrounded pseudo-paths leave semantic/spatial fidelity unresolved.',
implementation='Inspected the model forward inputs, BnB dataset construction/shuffling, and the pretraining driver. No corpus was downloaded and no candidate search was executed.',
code=[dict(path='airbert.py',locator='forward nearline62',finding='The model consumes text tokens and image-region features for multimodal scoring.'),dict(path='utils/dataset/bnb_dataset.py',locator='load_shuffler284–286; caption construction288 onward; negatives536 and587–593',finding='Shufflers produce negative captions/images and return them with positives, confirming the supervision mechanism.'),dict(path='train_bnb.py',locator='training entrypoint and loss aggregation',finding='Pretraining is an optimization stage; inference is not training-free use of an unchanged general VLM.')],
bottlenecks=[dict(description='Listing membership and shuffled order do not guarantee a valid navigable transition or faithful directional language.',evidence='Pseudo-path construction §3; Table5 direction errors',kind='data/methodological',status='Partially addressed',followups=['RoomTour3D video/geometry data','ScaleVLN rendered traversable environments','SRDF consistency filtering'],confidence='high'),dict(description='Exploration reranking obtains high SR at extreme movement cost; compare physically charged trajectories and SPL.',evidence='Table8 SR77/TL687/SPL0.01',kind='inference cost',status='Partially addressed',followups=['DUET single-run global navigation'],confidence='high')],followups=['https://roomtour3d.github.io','https://github.com/wz0919/ScaleVLN'])

add('prevalent',year=2020,venue='CVPR 2020',pages=[1,3,4,5,6],
problem='Pretrain representations using navigation-specific image–instruction–action triplets to transfer across embodied instruction tasks. Unlike later history-aware policies, its pretraining action prediction conditions on a current observation and instruction.',
method='PDF pp3–5:36 panoramic ResNet view features (2048 visual+128 angle dimensions) are projected into a768-dimensional Transformer with9 language,1 vision and3 cross-modal layers. Masked language modeling hides15% of words; action prediction uses a CLS representation to classify the next panoramic direction. For triplet (W,V,a), L_AP=−log pθ(a|W,V); MLM is cross entropy of masked words conditioned on unmasked language and views. These objectives do not explicitly supervise temporal memory. Training uses104k human-derived triplets and approximately6.482M synthetic triplets from1.02M generated instructions, totaling6.582M. Reported pretraining uses8V100,20epochs,AdamW5e−5. Downstream R2R integrates pretrained language features into an EnvDrop/LSTM agent; this differs from later recurrent VLN-BERT, which recurrently uses the multimodal backbone. Inference follows the trained downstream policy.',
novelty='Navigation-specific multimodal/action pretraining is the contribution, rather than a new online map or world model. Transfer across R2R,CVDN,HANNA supports usefulness of the representation; the data scale and downstream policy remain material parts of the result.',
results='AUTHOR EXPERIMENT: Table1 p6 reports test SR54/SPL51 for the single-instruction setting and59/56 for the multiple-instruction setting. They are separate protocols. VERDICT: effective task-oriented pretraining, but its state-independent pretraining cannot establish history-sensitive reasoning and synthetic instruction quality is not independently certified.',
implementation='The pinned main repository contains preprocessing assets/connectivity and README links to official PREVALENT_R2R and PREVALENT_HANNA applications. It is inaccurate to claim that the main repository itself contains the complete pretrained model/trainer. Application source inspection is tracked in the shared implementation supplement; release links alone are not execution evidence.',
repository_status='Main repository inspected; downstream application separate',
bottlenecks=[dict(description='Current-state action pretraining does not explicitly resolve visually aliased states requiring past observations.',evidence='§3 image–text–action triplet objective',kind='architectural/training',status='Partially addressed',followups=['Recurrent VLN-BERT','HAMT'],confidence='high'),dict(description='Millions of synthetic triplets still originate from a restricted set of environments and an imperfect speaker.',evidence='§4 pretraining data',kind='data',status='Partially addressed',followups=['ScaleVLN environment expansion','SRDF iterative consistency filtering'],confidence='high')],followups=['https://github.com/weituo12321/PREVALENT_R2R','https://github.com/YicongHong/Recurrent-VLN-BERT'])

add('speakerfollower',year=2018,venue='NeurIPS 2018',pages=[1,3,4,5,6],
problem='Human navigation instructions are scarce and an instruction-conditioned follower may choose routes whose visual content does not explain the instruction. A learned reverse-direction speaker supplies both additional training instructions and a route-compatibility score.',
method='PDF pp3–6: train an LSTM speaker PS(d|r) on human route–description pairs; generate descriptions for178k sampled shortest routes in training environments; train a follower PF(r|d) on augmented data then fine-tune on human data. The follower attends over language and36-view panoramic features and selects neighboring viewpoints or STOP. A state-factored search collects40 completed candidate routes. Final selection is argmaxr PS(d|r)^λ PF(r|d)^(1−λ), equivalently λlogPS+(1−λ)logPF; λ is near1. The inspected code evaluates0 and0.95 weights and can standardize scores. State-factored search merges candidates by physical state despite history-dependent LSTM states; therefore it is approximate. The physical traversal needed to obtain candidate observations must count in trajectory length.',
novelty='The same reverse instruction-generation model is used for both data augmentation and pragmatic inference. Panorama-level neighbor actions also change the action abstraction relative to the original low-level R2R baseline. These are separable sources of improvement, so the method is not merely a speaker loss added to an otherwise identical baseline.',
results='AUTHOR CLAIM/EXPERIMENT: the ablations in §4 attribute improvements to augmentation, panoramic actions, and speaker reranking. This review does not substitute later papers’ reproduced numbers for an uninspected original result table. VERDICT: influential training/inference decomposition, but speaker likelihood is a learned compatibility proxy and neither semantic entailment nor a calibrated probability of task completion. Search improves candidate coverage at added movement and compute cost.',
implementation='Inspected follower rollout/CE, speaker token likelihood, augmentation entrypoint, and rational reranking. The reranker explicitly constructs physically traversed trajectories when configured, so clean candidate paths and executed exploration paths must not be conflated.',
code=[dict(path='tasks/R2R/speaker.py',locator='lines179–182',finding='Speaker score sums token log likelihoods and trains with token NLL.'),dict(path='tasks/R2R/follower.py',locator='rollout lines430–538; state-factored search',finding='Follower trains on action CE and maintains recurrent state during rollout/search.'),dict(path='tasks/R2R/rational_follower.py',locator='lines85–106,131–150',finding='Physical path reconstruction is distinct from weighted speaker/follower candidate reranking; tested speaker weights include0.95.'),dict(path='tasks/R2R/data_augmentation_from_speaker.py',locator='entry_point lines35–83',finding='Speaker-generated and scored candidates form augmentation output.')],
bottlenecks=[dict(description='A high reverse-language likelihood can favor common descriptions without establishing exact route semantics; same-scene synthetic routes do not add environmental diversity.',evidence='Speaker likelihood objective and training-scene augmentation §3',kind='data/methodological',status='Partially addressed',followups=['ScaleVLN','SRDF','AirBERT'],confidence='medium'),dict(description='Candidate search observes and traverses extra paths, creating a distinct resource protocol.',evidence='§3 search; rational_follower physical trajectory reconstruction',kind='inference cost',status='Partially addressed',followups=['FAST','DUET'],confidence='high')],followups=['https://github.com/Kelym/FAST','https://github.com/wz0919/VLN-SRDF'])

add('selfmonitoring',year=2019,venue='ICLR 2019',pages=[1,3,4,5,6],
problem='An agent needs to estimate whether its movement advances instruction completion and to detect deterioration before committing to a wrong branch. The paper estimates progress using supervised distance-to-goal targets rather than human labels of clause completion.',
method='PDF pp3–5: a co-grounding LSTM attends to current panoramic views and instruction words. Its progress monitor combines prior hidden state, current memory cell, grounded visual context, and the vector of text-attention weights to predict scalar p̂t∈[−1,1] using tanh. The target is pt=(d0−dt)/d0, overridden to1 when dt≤3m; it can be negative when moving farther from the goal. Training uses weighted action CE and squared progress error. Although the PDF’s printed Eq6 has a problematic negative sign on the MSE term, inspected code positively adds λMSE+(1−λ)CE; the implementation therefore minimizes squared error. At inference the monitor weights search candidates and can trigger backtracking when predicted progress decreases. Thus a progress monitor plus rollback is already established prior art.',
novelty='Auxiliary progress estimation jointly regularizes visual–language grounding and supplies an inference heuristic. The progress signal is distance based; an attention alignment visualization does not prove that the monitor represents semantic instruction completion.',
results='AUTHOR EXPERIMENT: Table1 p6 contains search results whose unrecorded-path and leaderboard movement-accounting interpretations differ: reported57SR/51SPL on the clean search path corresponds to57SR/2SPL when actual exploration is charged; augmented search reaches61SR with SPL2 under that accounting. VERDICT: progress provides useful guidance, but efficiency claims require the correct path protocol. A monotone goal-distance target can penalize a valid instruction-mandated detour.',
implementation='Inspected co-grounding policy, target construction, loss sign, rollout, and rollback candidate logic. The code resolves the printed loss-sign ambiguity; no training run was performed.',
code=[dict(path='tasks/R2R-pano/agents/pano_agent.py',locator='lines156–181',finding='Target is normalized start-to-goal distance improvement, with≤3m override and positive MSELoss.'),dict(path='tasks/R2R-pano/agents/pano_agent.py',locator='lines311–329 and602–634',finding='Positive weighted CE/MSE training; inference compares progress scores and records exploration/rollback.'),dict(path='tasks/R2R-pano/models/policy_model.py',locator='co-grounding forward definitions lines57 onward',finding='Visual candidate and language attentions feed the recurrent action policy.')],
bottlenecks=[dict(description='Distance progress conflates geometric goal approach with following an instruction that may require a detour or intermediate landmark.',evidence='Target formula/code156–169; deduction for non-shortest instructions',kind='supervision',status='Partially addressed',followups=['Regretful Agent','RxR longer path-faithfulness tasks'],confidence='high'),dict(description='Progress is not calibrated as a completion probability and search gains incur physical backtracking.',evidence='Tanh regression target; Table1 protocol',kind='methodological/inference cost',status='Partially addressed',followups=['FAST','DUET'],confidence='high')],followups=['https://github.com/chihyaoma/regretful-agent','https://github.com/Kelym/FAST'])

add('regretful',year=2019,venue='CVPR 2019',pages=[1,3,4,5,6],
problem='Recover from mistaken local actions while avoiding repeated oscillation between previously visited viewpoints. The method extends the self-monitoring agent with a learned forward-versus-rollback decision and node-specific progress memory.',
method='PDF §4 pp3–5: compute progress p̂t and its difference Δpt=p̂t−p̂t−1. A learned2-way softmax gate mixes forward embedding mf (instruction/current state) with rollback embedding mb (previous navigable direction): m=αfmf+αbmb. Progress values are detached before the gate, so action-loss gradients do not reshape the monitor through this path. A dictionary stores each visited node’s last progress; candidate features concatenate the difference between current progress and the stored value, tiled to balance feature scale. Unvisited nodes receive marker1 and STOP0. A post-rollback mask prevents immediate oscillation. Train with action CE, positive progress MSE, and entropy regularization βΣaπa logπa (β=.01, negative entropy encourages exploration); inference greedily selects an action. Memory is keyed by exact viewpoint identity, a simulator-provided assumption.',
novelty='Learned rollback mixing plus persistent per-node progress markers extends earlier heuristic rollback. Neither storing visited progress nor using progress changes as a recovery trigger is new to a prospective2027 proposal.',
results='AUTHOR EXPERIMENT: Table1 p6 augmented test SR/SPL48/40 versus self-monitoring43/32. Table2 unaugmented regret-only47/37, marker-only44/32, combined48/37 show both components can help, with non-additive effects. VERDICT: useful local recovery under graph localization; it does not establish calibrated error detection or globally optimal recovery. The distance-derived target inherits the mismatch with semantically necessary detours.',
implementation='Inspected forward/rollback embeddings, detached marker and gate, node memory, entropy and CE/MSE loss, and action rollout.',
code=[dict(path='tasks/R2R-pano/models/policy_model.py',locator='lines126–157',finding='Detached progress difference drives2-way rollback attention; current-minus-stored progress features affect action logits.'),dict(path='tasks/R2R-pano/agents/pano_agent.py',locator='lines381–437',finding='Per-episode dictionary tracks node progress; positive MSE/CE plus negative-entropy regularization trains the agent.')],
bottlenecks=[dict(description='Local rollback and an oscillation mask do not provide multi-step global route planning; distance progress can misclassify valid detours.',evidence='§4 policy and distance target; code gate',kind='methodological',status='Partially addressed',followups=['FAST frontier search','DUET graph routing'],confidence='high'),dict(description='Progress markers require reliable node identity and do not quantify map localization uncertainty.',evidence='Dictionary keyed by simulator viewpoint',kind='operating assumption',status='Uncertain because evidence is insufficient',followups=['Continuous VLN mapping methods'],confidence='high')],followups=['https://github.com/Kelym/FAST','https://github.com/cshizhe/VLN-DUET'])

add('tacticalrewind',year=2019,venue='CVPR 2019',pages=[1,3,4,5,6],
problem='Local navigation policies need a systematic means to leave an unproductive branch and compare plausible goal locations without committing permanently to the first STOP. FAST treats frontier choice and final goal ranking as distinct decisions.',
method='PDF §2/Algorithm1 pp3–5: maintain frontier queue QF of partial routes/actions scored by exploration heuristic L, and candidate queue QC of possible completed routes scored by goal function G. Exploitation follows the local best action until confusion/loops; exploration selects the best frontier. A visited transition graph supports physical backtracking. L may aggregate raw action logits rather than log-softmax; G combines progress, speaker likelihood and path-score statistics through a trained reranker. Short search stops on a local stopping criterion; long search runs a fixed expansion budget. Every visited location can become a final goal candidate. Raw-logit accumulation avoids one softmax-normalization artifact discussed in the paper, but is not theoretically calibrated: adding an arbitrary state-dependent constant to all logits preserves the action distribution while changing summed-logit route ranking. This is a mathematical invariance counterexample, not an executed benchmark result.',
novelty='Explicit separation of exploration and goal selection, organized backtracking, and plug-in search over existing followers. It directly anticipates proposals to decouple movement from stopping or rerank visited goal candidates; a new contribution must go beyond that abstraction.',
results='AUTHOR EXPERIMENT: Table1 p6 short search test SR54/SPL41/TL22.08m; long search61/3/196.53m. Self-monitoring beam search has61SR/2SPL/373.09m. Table2 plug-in validation improvements for Speaker-Follower37→43SR and self-monitoring47→56SR demonstrate some policy independence. VERDICT: improved search efficiency relative to a particular beam baseline, with a substantial SR–movement tradeoff; no proof of global score comparability.',
implementation='Inspected frontier expansion, raw-logit/log-prob options, separate ending queue, final candidate reranker, and physical return path. This is concrete released prior art for goal-candidate return behavior.',
code=[dict(path='follower.py',locator='lines844–917',finding='Tracks logit/log-prob summaries; selectively expands topK actions; routes STOP candidates to ending_queue separately from frontier nodes.'),dict(path='follower.py',locator='lines966–986',finding='Goal reranker uses length/logit/log-prob/progress/speaker features, then realistic_jumping returns through the visited graph.'),dict(path='follower.py',locator='lines542–551 and658–666',finding='Progress MSE and action CE training remain separate from search heuristics.'),dict(path='run_search.py',locator='search setup and sweep entrypoints',finding='Search settings are explicit experiment choices and must be matched in comparisons.')],
bottlenecks=[dict(description='Higher success consumes far more movement; a fixed expansion budget is not adaptive value-of-information control.',evidence='Table1 short/long comparison',kind='inference cost',status='Partially addressed',followups=['DUET global single-run policy'],confidence='high'),dict(description='Raw-logit heuristic is sensitive to arbitrary state-dependent offsets even when local action probabilities are unchanged.',evidence='L definition §2; softmax invariance deduction; no empirical claim',kind='score identifiability',status='Still unresolved in the reviewed literature',followups=[],confidence='high')],followups=['https://github.com/cshizhe/VLN-DUET'])

add('rcm',year=2019,venue='CVPR 2019',pages=[1,3,4,5,6],
problem='Use both goal-reaching reinforcement and route–instruction consistency to train a navigator, then adapt using unlabeled instructions in additional environments. Access to unseen environments during adaptation is a different evaluation regime from zero-shot unseen-scene generalization.',
method='PDF pp3–5: a recurrent reasoning navigator attends to instruction words and then to visual candidates. A fixed cross-modal matching critic estimates length-normalized instruction likelihood given an executed trajectory using a reverse sequence model. Supervised action-CE warm-start is followed by REINFORCE with extrinsic distance-progress/goal reward and intrinsic critic reward; γ=.95. For trajectory τ and instruction W, the policy term is −Σt logπθ(at|ht,W)At, where At includes return from these rewards. Self-supervised imitation learning (SIL) samples routes for unlabeled instructions, retains high-critic-score trajectories in replay, and imitates them. Eq16’s reward-weighted objective and Eq17’s simplified imitation update should not be described as algebraically identical without the authors’ approximation. Reported Adam rates are1e−4 supervised and1e−5 RL/SIL; ResNet is frozen and GloVe is fine-tuned. Inference uses the resulting trained navigator, not online gradient-free VLM prompting.',
novelty='Cycle-style matching reward and self-supervised route replay combine language consistency with goal reinforcement. The critic is a learned proxy, not an independent semantic oracle; self-training may inherit its preferences.',
results='AUTHOR EXPERIMENT: Table1 p6 test RCM SR43.1/SPL35; SIL in training environments43/38; SIL with unseen environments60.5/59. The latter explicitly uses unseen-environment adaptation and must not be compared as the same zero-shot condition. VERDICT: evidence for adaptation and consistency training, but not proof that the matching score certifies instruction entailment or that gains transfer without target-environment access.',
implementation='An official executable repository was not verified in the assignment search scope. No implementation behavior is inferred from similar repositories. The paper’s objectives and experiment protocols are available; code reproducibility remains an evidence gap.',
bottlenecks=[dict(description='Learned critic and policy can agree on semantically wrong but likely trajectories; no independent entailment guarantee is supplied.',evidence='Matching likelihood and SIL replay §3',kind='self-training/verifier bias',status='Partially addressed',followups=['SRDF bidirectional consistency filtering','CAST counterfactual relabeling lead'],confidence='medium'),dict(description='Unseen-environment SIL trades zero-shot generalization for target-environment interaction/training.',evidence='Table1 evaluation footnote and SIL setup',kind='protocol/resource tradeoff',status='Shifted into another cost or limitation',followups=['IVLN persistent experience','test-time adaptation methods'],confidence='high')],followups=['https://github.com/wz0919/VLN-SRDF','https://arxiv.org/abs/2508.13446'],limitations='Official code not located in documented search scope; this is not a claim that none exists. No benchmark executed.')

add('r2r',year=2018,venue='CVPR 2018',pages=[1,3,4,5,6],
problem='Define visually grounded natural-language navigation in realistic indoor panoramas. Matterport3D Simulator uses90 buildings, approximately10,800 viewpoints and194,400RGBD images; a graph discretizes traversable locations, so the benchmark does not directly test collision control, continuous localization, or dynamic obstacles.',
method='PDF pp3–6: weighted undirected navigation edges are checked by ray tracing/manual inspection, generally between viewpoints within5m (average spacing2.25m). R2R samples7,189 shortest paths of4–6edges and>5m and collects3instructions per path:21,567 instructions averaging29words. Annotators are explicitly told that exact path following is not necessary if the goal is reached. The original baseline is an attention sequence-to-sequence LSTM using ResNet152 image features and previous action, choosing left/right/up/down30-degree rotations, forward to a visible neighbor, or STOP. This differs from later panoramic graph-neighbor action abstractions. Evaluation measures endpoint graph distance, success within3m, and oracle success at the closest visited location, ignoring final orientation. OSR and SR therefore distinguish visiting from stopping, but their difference alone does not identify why stopping failed.',
novelty='A realistic photo-based simulator, connected navigation graph, human route descriptions, and held-out-building evaluation established the VLN task. Endpoint-oriented annotation is an intentional benchmark property, so instruction-path faithfulness requires additional metrics/datasets rather than assuming all goal shortcuts violate R2R’s original contract.',
results='AUTHOR DATA EVIDENCE: §3–4 provides scene/path/instruction statistics and explicit success definitions. The original split uses61train,11unseen-validation,18test buildings. VERDICT: foundational for controlled semantic navigation, with static graph/localization assumptions and acknowledged scene bias toward tidy, spacious homes (p4). Later numeric SR improvements should not be interpreted as equivalent progress in real robot navigation.',
implementation='Inspected original agent, model, and evaluator source. Their six-action sequence model and graph-distance evaluator provide the reference protocol; later panoramic candidates change action difficulty and observability.',
code=[dict(path='tasks/R2R/agent.py',locator='Seq2SeqAgent action definitions and rollout',finding='Low-level turn/look/forward/end actions are distinct from later panoramic neighbor actions.'),dict(path='tasks/R2R/model.py',locator='EncoderLSTM and attention decoder',finding='Sequence encoder and image-conditioned recurrent decoder implement the original baseline.'),dict(path='tasks/R2R/eval.py',locator='Evaluation._score_item and score',finding='Uses shortest-path graph distance for endpoint and oracle proximity.')],
bottlenecks=[dict(description='Endpoint success can coexist with failure to follow an intended route; OSR–SR cannot isolate softmax competition, grounding, exploration, or goal-estimation causes.',evidence='Annotation instructions p5 and metric definitions p6',kind='evaluation/task scope',status='Partially addressed',followups=['RxR dense path grounding','nDTW/SDTW evaluation','REVERIE object grounding'],confidence='high'),dict(description='Static panoramas, known graph adjacency and exact viewpoint state bypass perception/control/localization failures encountered by robots.',evidence='Simulator construction pp3–4',kind='operating assumption',status='Partially addressed',followups=['VLN-CE','Cross-Modal Map Learning','BEVBert/VER continuous variants'],confidence='high')],followups=['https://github.com/google-research-datasets/RxR','https://github.com/YuankaiQi/REVERIE'])
